import{_ as a,o as i,c as e,a0 as t}from"./chunks/framework.DhQjJcnt.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md","lastUpdated":null}'),n={name:"quickstart.md"};function l(p,s,h,d,o,c){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>从拿到二进制到打通第一条隧道，大约 5 分钟。全程只需要三样东西：</p><ol><li>一台有公网 IP 的服务器（信令服务器，租的 VPS 即可）</li><li>房主电脑（跑游戏/服务的那台）</li><li>访客电脑（朋友那台）</li></ol><h2 id="第-1-步-部署信令服务器" tabindex="-1">第 1 步：部署信令服务器 <a class="header-anchor" href="#第-1-步-部署信令服务器" aria-label="Permalink to &quot;第 1 步：部署信令服务器&quot;">​</a></h2><p>在公网服务器上执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 构建（首次较慢）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动信令服务器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relay-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:8081</span></span></code></pre></div><p>启动后三个服务同时就绪：</p><ul><li><strong>HTTP REST</strong>（8080/tcp）：房间注册与查询</li><li><strong>UDP 公网探测</strong>（8080/udp）：客户端学习自己的公网地址</li><li><strong>TCP 中继</strong>（8081/tcp）：打洞失败时的数据转发通道</li></ul><blockquote><p>记得在云厂商安全组和系统防火墙放行 <code>8080/tcp</code>、<code>8080/udp</code>、<code>8081/tcp</code>。</p></blockquote><p>服务器端也可以直接用打包好的二进制，见<a href="./server">部署信令服务器</a>的 systemd 方式。</p><h2 id="第-2-步-配置客户端" tabindex="-1">第 2 步：配置客户端 <a class="header-anchor" href="#第-2-步-配置客户端" aria-label="Permalink to &quot;第 2 步：配置客户端&quot;">​</a></h2><p>房主和访客都需要一份指向该服务器的配置（默认配置指向 <code>127.0.0.1</code>，仅本机联调可用）：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/server.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://你的服务器IP:8080&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # HTTP 信令</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的服务器IP:8081&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # TCP 中继</span></span></code></pre></div><p>通过 <code>--config</code> 指定：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/server.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span></code></pre></div><h2 id="第-3-步-房主创建房间" tabindex="-1">第 3 步：房主创建房间 <a class="header-anchor" href="#第-3-步-房主创建房间" aria-label="Permalink to &quot;第 3 步：房主创建房间&quot;">​</a></h2><p>在运行游戏/服务的那台机器上：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:25565</span></span></code></pre></div><p>其中 <code>--service</code> 是房主本地服务的地址（默认 <code>127.0.0.1:25565</code>）。输出示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Room created : game-a3f9c2</span></span>
<span class="line"><span>  Signaling    : http://你的服务器IP:8080</span></span>
<span class="line"><span>  Local service: 127.0.0.1:25565</span></span>
<span class="line"><span>  Waiting for a guest to join ...</span></span></code></pre></div><p>把 <strong><code>game-a3f9c2</code></strong> 发给朋友。</p><h2 id="第-4-步-访客加入" tabindex="-1">第 4 步：访客加入 <a class="header-anchor" href="#第-4-步-访客加入" aria-label="Permalink to &quot;第 4 步：访客加入&quot;">​</a></h2><p>在朋友机器上：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-a3f9c2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:25565</span></span></code></pre></div><p><code>--listen</code> 是访客本地要监听的端口（默认 <code>127.0.0.1:25565</code>）。输出示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Joined room : game-a3f9c2</span></span>
<span class="line"><span>  Host address: 你的服务器IP:xxx</span></span>
<span class="line"><span>  Local listen: 127.0.0.1:25565</span></span>
<span class="line"><span>  Punching through NAT ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt;&gt; P2P direct link established with 你的服务器IP:xxx   ← 打洞成功！</span></span></code></pre></div><p>此时朋友连接自己电脑的 <code>127.0.0.1:25565</code>，流量即到达房主的 <code>127.0.0.1:25565</code>。</p><p>如果打洞失败，会自动回退：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; UDP hole punching failed, falling back to relay ...</span></span>
<span class="line"><span>&gt;&gt;&gt; relay connected, waiting for host ...</span></span></code></pre></div><p>隧道依然可用，只是数据经过服务器转发（见<a href="./architecture">网络原理</a>）。</p><h2 id="最小可用命令" tabindex="-1">最小可用命令 <a class="header-anchor" href="#最小可用命令" aria-label="Permalink to &quot;最小可用命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>最小命令</th><th>说明</th></tr></thead><tbody><tr><td>房主</td><td><code>frp-sh game create</code></td><td>所有参数均有默认值</td></tr><tr><td>访客</td><td><code>frp-sh game join game-xxxxxx</code></td><td>只需房间号</td></tr><tr><td>服务器</td><td><code>frp-sh serve</code></td><td>监听 0.0.0.0:8080/8081</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cli">命令参考</a> 查看全部参数</li><li><a href="./advanced">高级用法</a> 加密、多连接等进阶配置</li><li><a href="./faq">故障排查 FAQ</a> 遇到问题先看这里</li></ul>`,34)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
